module benchmark/solution

type State = Idle | HasCredit(int) | Dispensing(int)

type Event = Insert(int) | Select(int) | DispenseDone

type StepResult = Ok(State) | Err(string)

pure func price(code: int) -> int =
  match code {
    1 => 125,
    2 => 75,
    3 => 100,
    _ => 0 - 1
  }

pure func selectItem(c: int, code: int) -> StepResult {
  let p = price(code);
  if p < 0 then Err("unknown_item")
  else if c < p then Err("insufficient_funds")
  else Ok(Dispensing(c - p))
}

pure func step(state: State, event: Event) -> StepResult =
  match state {
    Idle => match event {
      Insert(n) => Ok(HasCredit(n)),
      Select(_) => Err("no_credit"),
      DispenseDone => Err("not_dispensing")
    },
    HasCredit(c) => match event {
      Insert(n) => Ok(HasCredit(c + n)),
      Select(code) => selectItem(c, code),
      DispenseDone => Err("not_dispensing")
    },
    Dispensing(_) => match event {
      Insert(_) => Err("busy"),
      Select(_) => Err("busy"),
      DispenseDone => Ok(Idle)
    }
  }

pure func showState(s: State) -> string =
  match s {
    Idle => "IDLE",
    HasCredit(n) => "CREDIT(${show(n)})",
    Dispensing(ch) => "DISPENSING(${show(ch)})"
  }

func run(state: State, events: [Event]) -> () ! {IO} =
  match events {
    [] => (),
    e :: rest => match step(state, e) {
      Ok(s) => {
        println("ok: ${showState(s)}");
        run(s, rest)
      },
      Err(reason) => {
        println("err: ${reason}");
        run(state, rest)
      }
    }
  }

export func main() -> () ! {IO} =
  run(Idle, [Insert(50), Select(1), Insert(100), Select(1), Insert(50), DispenseDone, Select(2), Insert(100), Select(2), DispenseDone])

